    def test_character_human_research_dossiers_are_colocated_and_wrapped(self) -> None:
        target_dir = (
            repo_root()
            / "corpus/001_oracle-characters/001_000001-000100_obs-char-bucket_oracle-characters/"
            / "001_obs-char-000001_hust-obc-cat-0001_oracle-character"
        )
        dossier_path = target_dir / "05_human-research-dossier.md"
        review_path = target_dir / "06_human-review-sheet.md"
        index_path = target_dir / "07_research-dossier-index.json"
        self.assertTrue(path_exists(dossier_path), dossier_path)
        self.assertTrue(path_exists(review_path), review_path)
        self.assertTrue(path_exists(index_path), index_path)

        dossier = dossier_path.read_text(encoding="utf-8")
        review = review_path.read_text(encoding="utf-8")
        for text in [dossier, review]:
            for line in text.splitlines():
                if not line.startswith("!["):
                    self.assertLessEqual(len(line), 80, line)
        self.assertIn("Reading, Meaning, And Dataset Label", dossier)
        self.assertIn("Inscription Occurrences And Text Context", dossier)
        self.assertIn("Provenance, Findspot, Collection, And Period", dossier)
        self.assertIn("Decipherment History And Disputes", dossier)
        self.assertIn("Glyph Observation Checklist", dossier)
        self.assertIn("字形观察记录", dossier)
        self.assertIn(
            "Which visible strokes, outlines, breaks, or uncertain marks",
            dossier,
        )
        self.assertIn("哪些可见笔画、轮廓、残缺或不确定痕迹需要记录？", dossier)
        self.assertIn(
            "Which source image or gallery item supports each observation?",
            dossier,
        )
        self.assertIn("哪张来源图像或 gallery 条目支持每条观察？", dossier)
        self.assertIn("人类研究档案", dossier)
        self.assertIn("考古档案覆盖", dossier)
        self.assertIn("缺失项", dossier)
        self.assertIn("具体待查问题", dossier)
        self.assertIn("需要核对哪些卜辞、图版或著录号", dossier)
        self.assertIn("下一步应打开哪些来源记录", dossier)
        self.assertIn("待查：需要核对来源释读、释读史或争议记录", dossier)
        self.assertIn("待查：需要核对卜辞编号、全文或 OCR、图版号和字位", dossier)
        self.assertNotIn("not_collected", dossier)
        self.assertIn("人工复核单", review)
        self.assertIn("未复核释读必须保持候选状态", review)
        self.assertIn("no_claim", review)
        for fragment in ("浜", "绠€", "鐮", "缂哄け", "鑰冨彜"):
            self.assertNotIn(fragment, dossier)
            self.assertNotIn(fragment, review)

        index = json.loads(index_path.read_text(encoding="utf-8"))
        self.assertEqual(index["project_id"], "obs-char-000001")
        self.assertEqual(index["claim_boundary"], "dossier_index_only_no_decipherment_claim")
        self.assertIn("05_human-research-dossier.md", index["human_files"])
        self.assertIn("07_research-dossier-index.json", index["ai_files"])
        self.assertIn("accepted_reading_and_meaning", index["missing_sections"])
        self.assertEqual(index["human_language_coverage"]["simplified_chinese"], "present")
        self.assertIn("glyph_images", index["archaeological_folder_coverage"])
        self.assertIn("decipherment_history", index["archaeological_folder_coverage"])
        self.assertFalse(
            any(
                "not_collected" in value
                for value in index["archaeological_folder_coverage"].values()
            )
        )
        self.assertEqual(
            index["archaeological_folder_coverage"]["variant_forms"],
            "needs_human_variant_review_route",
        )
        self.assertEqual(
            index["archaeological_folder_coverage"]["decipherment_history"],
            "needs_bibliography_and_dispute_review_route",
        )

