    def test_character_inscription_linkage_audit_is_explicitly_candidate_only(self) -> None:
        module = load_character_inscription_linkage_audit_module()
        text, index = module.build_audit(repo_root())
        self.assertIn("Character-Inscription Linkage Audit", text)
        self.assertIn("Character-inscription edges promoted: 0", text)
        self.assertEqual(index["packet_count"], 612)
        self.assertEqual(index["packets_with_explicit_character_link_fields"], 0)
        self.assertEqual(index["character_inscription_edge_count"], 0)
        self.assertEqual(
            index["review_status"],
            "candidate_only_no_character_inscription_edge_promoted",
        )
        for line in text.splitlines():
            self.assertLessEqual(len(line), 80, line)

    def test_evolution_candidate_local_materials_are_colocated(self) -> None:
        self.assertEqual(check_evolution_candidate_local_materials(repo_root()), [])

        map_path = (
            repo_root()
            / "project_registry/002_project-id-to-source-reference-map/"
            / "005_evolution-candidate-id-source-map.csv"
        )
        with map_path.open("r", encoding="utf-8-sig", newline="") as file:
            rows = list(csv.DictReader(file))
        self.assertEqual(len(rows), 13714)
        self.assertEqual(rows[0]["project_id"], "obs-evo-cand-000001")
        self.assertEqual(rows[-1]["project_id"], "obs-evo-cand-013714")
        for row in [rows[0], rows[-1]]:
            object_dir = repo_root() / row["canonical_path"]
            self.assertTrue((object_dir / "README.md").exists())
            self.assertTrue((object_dir / "01_candidate-evolution-packet.json").exists())
            self.assertTrue((object_dir / "02_evolution-source-index.csv").exists())
            self.assertTrue((object_dir / "03_era-source-code-index.csv").exists())
            self.assertTrue((object_dir / "04_human-review-sheet.md").exists())
            self.assertTrue((object_dir / "05_image-reference-route-index.csv").exists())
            self.assertTrue((object_dir / "06_image-reference-route-gallery.md").exists())
            self.assertTrue((object_dir / "07_human-evolution-dossier.md").exists())
            self.assertTrue((object_dir / "08_evolution-dossier-index.json").exists())
            self.assertTrue((object_dir / "09_cross-period-review-dossier.md").exists())
            self.assertTrue((object_dir / "10_cross-period-review-index.json").exists())
            self.assertTrue((object_dir / "11_evolution-review-fact-matrix.md").exists())
            self.assertTrue((object_dir / "12_modern-label-caution-review.md").exists())
            self.assertTrue((object_dir / "13_modern-label-caution-index.json").exists())
            self.assertTrue((object_dir / "14_human-research-readiness-review.md").exists())
            self.assertTrue((object_dir / "15_human-research-readiness-index.json").exists())
            readme_text = (object_dir / "README.md").read_text(encoding="utf-8")
