    def test_character_asset_graph_edges_link_local_glyph_images(self) -> None:
        path = repo_root() / "corpus/008_relationship-graph/009_character-asset-graph-edges.jsonl"
        rows = [
            json.loads(line)
            for line in path.read_text(encoding="utf-8").splitlines()
            if line.strip()
        ]
        self.assertEqual(len(rows), 10996)
        self.assertEqual(
            [row["edge_id"] for row in rows],
            [f"edge-character-asset-glyph-candidate-{index:04d}" for index in range(1, 10997)],
        )
        asset_index_path = repo_root() / "project_registry/004_asset-source-and-rights-index/001_asset-source-index.csv"
        with asset_index_path.open("r", encoding="utf-8-sig", newline="") as file:
            asset_rows = list(csv.DictReader(file))
        expected_pairs = [
            (row["related_project_ids"], row["asset_id"])
            for row in sorted(
                [
                    row
                    for row in asset_rows
                    if row["asset_type"] == "glyph_candidate_image"
                    and row["related_project_ids"].startswith("obs-")
                ],
                key=lambda row: row["asset_id"],
            )
        ]
        self.assertEqual(
            [(row["source_node_id"], row["target_node_id"]) for row in rows],
            expected_pairs,
        )
        self.assertEqual(
            {row["edge_type"] for row in rows},
            {"CHARACTER_HAS_LOCAL_GLYPH_ASSET_CANDIDATE"},
        )
        self.assertEqual({tuple(row["source_ids"]) for row in rows}, {("src-hust-obc",)})
        self.assertEqual({row["confidence_level"] for row in rows}, {"high"})
        self.assertEqual({row["review_status"] for row in rows}, {"needs_human_visual_review"})
        self.assertTrue(all("not decipherment evidence" in row["evidence_note"] for row in rows))

