    def test_source_engineering_gap_review_logs_include_snapshot_evidence(self) -> None:
        path = (
            repo_root()
            / "corpus/009_statistics-and-derived-features/"
            / "102_ai-agent-source-engineering-gap-review-log-draft-manifest.csv"
        )
        with path.open("r", encoding="utf-8-sig", newline="") as file:
            rows = list(csv.DictReader(file))
        self.assertEqual(len(rows), 14)
        self.assertEqual(
            Counter(row["gap_type"] for row in rows),
            {
                "access_boundary_or_error_followup": 5,
                "checksum_or_failed_download_status_review_needed": 4,
                "safe_derived_record_decision_needed": 2,
                "source_field_map_needed": 3,
            },
        )
        self.assertEqual({row["draft_status"] for row in rows}, {"draft_not_collected"})
        self.assertEqual({row["evidence_collection_status"] for row in rows}, {"not_collected"})
        self.assertEqual({row["source_promotion_status"] for row in rows}, {"not_promoted"})
        self.assertTrue(all((repo_root() / row["draft_path"]).exists() for row in rows))
        first_text = (repo_root() / rows[0]["draft_path"]).read_text(encoding="utf-8")
        self.assertIn("Existing Metadata Snapshot / 已有 metadata 快照", first_text)
        self.assertIn("source-engineering-gap-evidence-snapshot-0001", first_text)
        self.assertIn("download_error:1", first_text)
        self.assertIn("download_log_file_size_bytes_total: `0`", first_text)
        self.assertNotIn("Evidence items / 证据条目: none", first_text)
        self.assertIn("no rights clearance", first_text)
        long_lines = []
        empty_evidence_paths = []
        for row in rows:
            path = repo_root() / row["draft_path"]
            text = path.read_text(encoding="utf-8")
            if "Evidence items /" in text:
                empty_evidence_paths.append(path.relative_to(repo_root()).as_posix())
            for line_number, line in enumerate(text.splitlines(), start=1):
                if len(line) > 80:
                    long_lines.append(
                        (path.relative_to(repo_root()).as_posix(), line_number, line)
                    )
        self.assertEqual(empty_evidence_paths, [])
        self.assertEqual(long_lines, [])

    def test_source_engineering_gap_review_queue_has_no_empty_evidence_logs(self) -> None:
        queue_dir = (
            repo_root()
            / "doc/public/user_research/009_source-engineering-gap-review-queues"
        )
        manifest_path = (
            repo_root()
            / "corpus/009_statistics-and-derived-features/"
            / "102_ai-agent-source-engineering-gap-review-log-draft-manifest.csv"
        )
        with manifest_path.open("r", encoding="utf-8-sig", newline="") as file:
            manifest_paths = {row["draft_path"] for row in csv.DictReader(file)}
        review_log_paths = {
            path.relative_to(repo_root()).as_posix()
            for path in sorted(queue_dir.glob("*_review-log.md"))
        }
        self.assertEqual(review_log_paths, manifest_paths)

        empty_evidence_files = []
        for path in sorted(queue_dir.glob("*_review-log.md")):
            text = path.read_text(encoding="utf-8")
            if "Evidence items / 证据条目: none" in text:
                empty_evidence_files.append(path.relative_to(repo_root()).as_posix())
            if "Evidence items /" in text:
                empty_evidence_files.append(path.relative_to(repo_root()).as_posix())
            if "not decided" in text:
                empty_evidence_files.append(path.relative_to(repo_root()).as_posix())
        self.assertEqual(empty_evidence_files, [])
        long_lines: list[tuple[str, int, int]] = []
        for path in sorted(queue_dir.glob("*.md")):
            text = path.read_text(encoding="utf-8")
            for line_number, line in enumerate(text.splitlines(), start=1):
                if len(line) > 80:
                    long_lines.append(
                        (path.relative_to(repo_root()).as_posix(), line_number, len(line))
                    )
        self.assertEqual(long_lines, [])

