    def test_source_pipeline_missing_evidence_chain_is_empty_after_applicability_review(self) -> None:
        stat_dir = repo_root() / "corpus/009_statistics-and-derived-features"
        for number in range(144, 186):
            paths = sorted(stat_dir.glob(f"{number:03d}_source-pipeline*"))
            self.assertEqual(len(paths), 1, number)
            path = paths[0]
            if path.suffix == ".csv":
                with path.open("r", encoding="utf-8-sig", newline="") as file:
                    reader = csv.DictReader(file)
                    self.assertIsNotNone(reader.fieldnames, path)
                    self.assertEqual(list(reader), [], path)
            else:
                data = json.loads(path.read_text(encoding="utf-8"))
                for key, value in data.items():
                    if key.endswith("_count") and isinstance(value, int):
                        self.assertEqual(value, 0, f"{path}: {key}")
                    if key in {
                        "routes",
                        "handoffs",
                        "assignment_items",
                        "handoff_items",
                        "source_summaries",
                    }:
                        self.assertEqual(value, [], f"{path}: {key}")

